import{_ as s,c as n,o as e,ag as p}from"./chunks/framework.B3RpK1bM.js";const g=JSON.parse('{"title":"语法设计","description":"","frontmatter":{},"headers":[],"relativePath":"zh_CN/syntax-design.md","filePath":"zh_CN/syntax-design.md","lastUpdated":1769658044000}'),t={name:"zh_CN/syntax-design.md"};function l(i,a,d,c,o,r){return e(),n("div",null,[...a[0]||(a[0]=[p(`<h1 id="语法设计" tabindex="-1">语法设计 <a class="header-anchor" href="#语法设计" aria-label="Permalink to &quot;语法设计&quot;">​</a></h1><p><a href="./">返回目录</a></p><p>为使得剧本写作与演出设计更加便利, 语法设计中对剧本与演出进行了一定程度的分离. 以下分别针对剧本和演出进行说明:</p><h2 id="剧本" tabindex="-1">剧本 <a class="header-anchor" href="#剧本" aria-label="Permalink to &quot;剧本&quot;">​</a></h2><h3 id="对话框" tabindex="-1">对话框 <a class="header-anchor" href="#对话框" aria-label="Permalink to &quot;对话框&quot;">​</a></h3><p>台词可以采用<code>对话框</code>展示:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[对话框]</span></span>
<span class="line"><span>这是采用对话框的显示方式</span></span>
<span class="line"><span>少女:这是对话框下少女的说话方式</span></span></code></pre></div><h3 id="全屏" tabindex="-1">全屏 <a class="header-anchor" href="#全屏" aria-label="Permalink to &quot;全屏&quot;">​</a></h3><p>还可以用<code>全屏</code>展示:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[全屏]</span></span>
<span class="line"><span>全屏支持显示多段内容</span></span>
<span class="line"><span>但不支持由角色说话</span></span>
<span class="line"><span>全屏状态下支持同时说12行</span></span>
<span class="line"><span>[全屏]</span></span>
<span class="line"><span>我们也可以再次定义以提前切换行数</span></span></code></pre></div><h3 id="选项" tabindex="-1">选项 <a class="header-anchor" href="#选项" aria-label="Permalink to &quot;选项&quot;">​</a></h3><p><code>选项</code>的展示方式与<code>对话框</code>和<code>全屏</code>相同, 但是会将选项的内容进行存储, 并允许玩家进行选择:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[选项]</span></span>
<span class="line"><span>{script:测试3.txt}跳转测试3</span></span>
<span class="line"><span>{jump:循环1}跳转循环1</span></span>
<span class="line"><span>继续</span></span>
<span class="line"><span>[全屏]</span></span>
<span class="line"><span>选择全屏以后可以看到这段话</span></span></code></pre></div><h3 id="专业名词" tabindex="-1">专业名词 <a class="header-anchor" href="#专业名词" aria-label="Permalink to &quot;专业名词&quot;">​</a></h3><p>台词支持bbcode语法, 我们可以通过使用以下方法定义一些专业名词:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[全屏]</span></span>
<span class="line"><span>这是一个[url=专业名词]专业名词[/url]</span></span></code></pre></div><p>通过选择专业名词会出现字典框, 我们可以在dictionary文件夹定义<code>专业名词.txt</code>文件, 实现设置专业名词的功能.</p><h2 id="演出" tabindex="-1">演出 <a class="header-anchor" href="#演出" aria-label="Permalink to &quot;演出&quot;">​</a></h2><h3 id="跳转" tabindex="-1">跳转 <a class="header-anchor" href="#跳转" aria-label="Permalink to &quot;跳转&quot;">​</a></h3><p>出现需要回溯的剧本位置时可以通过<code>@</code>设置跳转的<strong>标记位置</strong>, 比如以下方式:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@循环1</span></span>
<span class="line"><span>这里是一个死循环</span></span>
<span class="line"><span>{jump:循环1}</span></span></code></pre></div><p>在进行跳转时会回到<code>@循环1</code>的位置, 除了设置<strong>标记位置</strong>之外的演出方式统一用大括号进行管理, 比如以下方式:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{bg:封面.png}#切换封面</span></span>
<span class="line"><span>{少女:normal.png-1200x650-1.1}少女:大家好#设置立绘</span></span>
<span class="line"><span>{script:测试2.txt, jump:循环1}#跳转到测试2脚本的循环1位置</span></span></code></pre></div><h3 id="独立演出" tabindex="-1">独立演出 <a class="header-anchor" href="#独立演出" aria-label="Permalink to &quot;独立演出&quot;">​</a></h3><p>一般情况演出依赖于剧本的文字内容，当需要不以文字内容作为依附进行演出时（比如展示CG场景）可以添加持续时间将演出作为独立演出事件进行控制，比如以下方式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>少女:更换封面时会将在更新对话内容时一并更新</span></span>
<span class="line"><span>{bg:封面1.png}少女:比如更换[color=red]封面1[/color]时会与当前对话一并更新</span></span>
<span class="line"><span>{bg:封面2.png, wait:0}</span></span>
<span class="line"><span>少女:当识别到设置wait时需要先点击更新[color=blue]封面2[/color]以后才能再次点击更新以下对话</span></span>
<span class="line"><span>{bg:封面1.png, wait:3}</span></span>
<span class="line"><span>少女:wait不为0时需要等待[color=blue]封面1[/color]存在3秒后才会进行更新</span></span></code></pre></div><h3 id="演出参数" tabindex="-1">演出参数 <a class="header-anchor" href="#演出参数" aria-label="Permalink to &quot;演出参数&quot;">​</a></h3><p>以下定义了大括号内的参数如下:</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>例子</th></tr></thead><tbody><tr><td>bg</td><td>设置背景, 背景应该在<code>./image/background/</code>文件夹中</td><td>bg:封面.png</td></tr><tr><td>script</td><td>跳转到设定的脚本位置</td><td>script:测试3.txt</td></tr><tr><td>jump</td><td>跳转到设定的<strong>标记位置</strong></td><td>jump:循环1</td></tr><tr><td>wait</td><td>设置当前事件的维持时间(秒)</td><td>wait:0</td></tr><tr><td>ef</td><td>我想用来设置特效, 但是还未实现</td><td></td></tr><tr><td>[default]</td><td>用来设置角色立绘, [default]需要在<code>./image/</code>文件夹下具备对应名字, 里面定义的名称如下<code>[图片名称]-[图片高度]x[图片宽度]-[缩放比例]</code></td><td>少女:normal.png-1200x650-1.1</td></tr></tbody></table><h2 id="语序" tabindex="-1">语序 <a class="header-anchor" href="#语序" aria-label="Permalink to &quot;语序&quot;">​</a></h2><p>语序（语言顺序）是剧本与演出在执行时的调用顺序，Ezlang的语序规范如下所示：</p><h3 id="默认情况" tabindex="-1">默认情况 <a class="header-anchor" href="#默认情况" aria-label="Permalink to &quot;默认情况&quot;">​</a></h3><p>默认情况下演出依附剧本进行呈现，剧本自动匹配当前行的演出和下一行的演出，例如以下三个例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 例1</span></span>
<span class="line"><span>{bg:test.png}处于当前行</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 例2</span></span>
<span class="line"><span>处于当前行{bg:test.png}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 例3</span></span>
<span class="line"><span>处于当前行</span></span>
<span class="line"><span>{bg:test.png}</span></span></code></pre></div><h3 id="独立演出-1" tabindex="-1">独立演出 <a class="header-anchor" href="#独立演出-1" aria-label="Permalink to &quot;独立演出&quot;">​</a></h3><p>独立演出中演出不依附剧本进行呈现，按台本的先后顺序进行识别：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 例1</span></span>
<span class="line"><span>先发言后切换场景{bg:test.png, wait:0}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 例2</span></span>
<span class="line"><span>{bg:test.png, wait:0}先切换场景后发言</span></span></code></pre></div><h3 id="兼容语序" tabindex="-1">兼容语序 <a class="header-anchor" href="#兼容语序" aria-label="Permalink to &quot;兼容语序&quot;">​</a></h3><p>兼容语序用于非常规输出时用于兼容性运行。在切换展示类型时先单独调用不独立的演出，演出将自动搜索下一行台本进行适配：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[全屏]</span></span>
<span class="line"><span>{bg:test.png}</span></span>
<span class="line"><span>图片切换将绑定当前文本</span></span></code></pre></div>`,40)])])}const b=s(t,[["render",l]]);export{g as __pageData,b as default};
